  | 2, 0 => iarm2_0_0RB0LA_1LA1RC_0RD1RD_1LB1RB
  | 2, 1 => iarm2_1_0RB0LA_1LA1RC_0RD1RD_1LB1RB
  | _, _ => iarm0_0_0RB0LA_1LA1RC_0RD1RD_1LB1RB   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

