Definition iarm_0RB1RB_1LC1RC_1LD1RA_0RA0LD (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_0RB1RB_1LC1RC_1LD1RA_0RA0LD
  | 0, 1 => iarm0_1_0RB1RB_1LC1RC_1LD1RA_0RA0LD
  | 1, 0 => iarm1_0_0RB1RB_1LC1RC_1LD1RA_0RA0LD
  | 1, 1 => iarm1_1_0RB1RB_1LC1RC_1LD1RA_0RA0LD
  | 2, 0 => iarm2_0_0RB1RB_1LC1RC_1LD1RA_0RA0LD
  | 2, 1 => iarm2_1_0RB1RB_1LC1RC_1LD1RA_0RA0LD
  | _, _ => iarm0_0_0RB1RB_1LC1RC_1LD1RA_0RA0LD   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

Definition farm1_0_0RB1RB_1LC1RC_1LD1RA_0RA0LD : LRule :=
  mkLRule (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S1;S1;S1] [S1;S1;S1] 1 0 []))
          (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S0;S0;S0] [S0;S0;S0] 1 0 [S1;S1])) 6 10.
