  | 2, 0 => iarm2_0_1RB1LB_1RC1LD_0LD0RC_0LA1LA
  | 2, 1 => iarm2_1_1RB1LB_1RC1LD_0LD0RC_0LA1LA
  | _, _ => iarm0_0_1RB1LB_1RC1LD_0LD0RC_0LA1LA   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

