    exfalso; lia.
  }
  destruct d as [|d].
  {
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB____1LC1RD_0RB0LC_1LC1RA | exact ok_iarm2_0_1RB____1LC1RD_0RB0LC_1LC1RA]. }
    destruct r as [|r].
