(** The machine-level theorem, at the INSTRUCTION level: the board above
    runs on the machine wrapped at the pins, and
    [LadderCheckTr.boardph_neverqhtr] turns it into [NeverQuasiHaltsTr] of
    the machine itself. *)
Theorem nqhtr_1RB____1LC1RD_0RB0LC_1LC1RA : NeverQuasiHaltsTr tm_1RB____1LC1RD_0RB0LC_1LC1RA.
Proof.
  eapply (boardphL_neverqhtr tm_1RB____1LC1RD_0RB0LC_1LC1RA pins_1RB____1LC1RD_0RB0LC_1LC1RA FAM 1
    iarm_1RB____1LC1RD_0RB0LC_1LC1RA 1 1 farm_1RB____1LC1RD_0RB0LC_1LC1RA 1 1 fm1_1RB____1LC1RD_0RB0LC_1LC1RA fm2_1RB____1LC1RD_0RB0LC_1LC1RA padl_1RB____1LC1RD_0RB0LC_1LC1RA padr_1RB____1LC1RD_0RB0LC_1LC1RA
    0 vis_1RB____1LC1RD_0RB0LC_1LC1RA [2] 0).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
